function validate(raw){if(!object(raw)||raw.version!==1||!object(raw.units)||Object.keys(raw.units).length>SUBJECTS.length)throw Error('Invalid deep-lesson backup.');const out=blank();
 for(const [sub,records] of Object.entries(raw.units)){if(!SUBJECTS.includes(sub)||!object(records)||Object.keys(records).length>TRACKS[sub].length)throw Error('Invalid deep-lesson subject.');out.units[sub]={};
 for(const [idx,entry] of Object.entries(records)){if(!/^(0|[1-9]\d*)$/.test(idx)||+idx>=TRACKS[sub].length||!object(entry)||Object.keys(entry).some(k=>!['step','explored','done','reflection','completedAt'].includes(k)))throw Error('Invalid deep-lesson record.');
 if(!Number.isInteger(entry.step)||entry.step<0||entry.step>3||typeof entry.explored!=='boolean'||typeof entry.done!=='boolean'||typeof entry.reflection!=='string'||entry.reflection.length>600||typeof entry.completedAt!=='string'||entry.completedAt.length>35||(entry.completedAt&&!Number.isFinite(Date.parse(entry.completedAt)))||entry.done&&(entry.step!==3||!entry.explored||!entry.completedAt))throw Error('Invalid deep-lesson progress.');
 out.units[sub][idx]={step:entry.step,explored:entry.explored,done:entry.done,reflection:entry.reflection,completedAt:entry.completedAt};}}
 return out;}
