 present:{ser:['soy','eres','es','somos','sois','son'],estar:['estoy','estás','está','estamos','estáis','están'],ir:['voy','vas','va','vamos','vais','van'],tener:['tengo','tienes','tiene','tenemos','tenéis','tienen'],hacer:['hago','haces','hace','hacemos','hacéis','hacen'],querer:['quiero','quieres','quiere','queremos','queréis','quieren'],poder:['puedo','puedes','puede','podemos','podéis','pueden'],venir:['vengo','vienes','viene','venimos','venís','vienen'],decir:['digo','dices','dice','decimos','decís','dicen'],salir:['salgo','sales','sale','salimos','salís','salen'],saber:['sé','sabes','sabe','sabemos','sabéis','saben']},
 preterite:{ser:['fui','fuiste','fue','fuimos','fuisteis','fueron'],ir:['fui','fuiste','fue','fuimos','fuisteis','fueron'],estar:['estuve','estuviste','estuvo','estuvimos','estuvisteis','estuvieron'],tener:['tuve','tuviste','tuvo','tuvimos','tuvisteis','tuvieron'],hacer:['hice','hiciste','hizo','hicimos','hicisteis','hicieron'],querer:['quise','quisiste','quiso','quisimos','quisisteis','quisieron'],poder:['pude','pudiste','pudo','pudimos','pudisteis','pudieron'],venir:['vine','viniste','vino','vinimos','vinisteis','vinieron'],decir:['dije','dijiste','dijo','dijimos','dijisteis','dijeron'],saber:['supe','supiste','supo','supimos','supisteis','supieron'],leer:['leí','leíste','leyó','leímos','leísteis','leyeron']},
 imperfect:{ser:['era','eras','era','éramos','erais','eran'],ir:['iba','ibas','iba','íbamos','ibais','iban']},
