function conjugate(verb,tense,p){if(tense==='near')return presentIr[p]+' a '+verb;
 const special=irregular[tense]?.[verb];if(special)return special[p];
 const type=verb.slice(-2),root=verb.slice(0,-2),ar=type==='ar';
 if(tense==='present')return root+(ar?['o','as','a','amos','áis','an']:type==='er'?['o','es','e','emos','éis','en']:['o','es','e','imos','ís','en'])[p];
 if(tense==='preterite')return root+(ar?['é','aste','ó','amos','asteis','aron']:['í','iste','ió','imos','isteis','ieron'])[p];
 if(tense==='imperfect')return root+(ar?['aba','abas','aba','ábamos','abais','aban']:['ía','ías','ía','íamos','íais','ían'])[p];
 if(tense==='future')return (futureStem[verb]||verb)+['é','ás','á','emos','éis','án'][p];return verb;}
