const midi=n=>60+notes.indexOf(n);
function playNote(n){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;audioCtx??=new Audio();if(audioCtx.state==='suspended')audioCtx.resume();const osc=audioCtx.createOscillator(),g=audioCtx.createGain();osc.type='sine';osc.frequency.value=440*Math.pow(2,(midi(n)-69)/12);g.gain.setValueAtTime(0.0001,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.13,audioCtx.currentTime+.015);g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+.55);osc.connect(g).connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+.57)}catch{}}
