 const board=el('div','st216-keyboard');board.setAttribute('role','group');board.setAttribute('aria-label','Piano keyboard C4 to C5');notes.filter(n=>!n.includes('#')).forEach(n=>{const b=btn(n,()=>tap(n),'st216-white');b.dataset.note=n;board.append(b)});
