 if(index===1){const rhythm=el('div','st216-rhythm');const display=el('p','st216-muted','Tap four or more times at a steady pace.');rhythm.append(btn('Tap a steady beat',()=>{const t=performance.now();tapTimes.push(t);if(tapTimes.length>8)tapTimes.shift();if(tapTimes.length>1){const interval=(tapTimes[tapTimes.length-1]-tapTimes[0])/(tapTimes.length-1);display.textContent=interval>100&&interval<4000?`Your approximate pulse: ${Math.round(60000/interval)} beats/minute. Keep it comfortable, not perfect.`:'Keep tapping slowly to establish a pulse.'}explored()},'st216-main'),display);panel.append(rhythm)}
