function svg(tag,attributes){const v=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,val] of Object.entries(attributes||{}))v.setAttribute(k,String(val));return v}
function drawGraph(target,mode,params){target.replaceChildren();const s=svg('svg',{viewBox:'0 0 540 250',role:'img','aria-label':mode==='area'?'Graph of y equals x, divided into rectangles':'Graph of y equals x squared with selected points'});const bg=svg('rect',{x:0,y:0,width:540,height:250,fill:'transparent'});s.append(bg);const x0=50,y0=215,w=425,h=185,maxX=5;
 for(let i=0;i<=5;i++){const x=x0+i*w/maxX;s.append(svg('line',{x1:x,y1:24,x2:x,y2:y0,stroke:'#94a3b8','stroke-opacity':'.2'}));const tick=svg('text',{x,y:232,'text-anchor':'middle','font-size':12,fill:'currentColor'});tick.textContent=String(i);s.append(tick)}
 const maxY=mode==='area'?5:25;
 const point=(x,y)=>[x0+x*w/maxX,y0-(y/maxY)*h];s.append(svg('line',{x1:x0,y1:y0,x2:x0+w,y2:y0,stroke:'currentColor','stroke-opacity':'.65'}));
 if(mode==='area'){const b=params.b,n=params.n,dx=b/n;for(let i=0;i<n;i++){const height=i*dx,[left,bottom]=point(i*dx,0),[_,top]=point(i*dx,height);s.append(svg('rect',{x:left,y:top,width:Math.max(1,dx*w/maxX-1),height:bottom-top,fill:'#67a99b','fill-opacity':'.35',stroke:'#239f89','stroke-width':.6}))}}
 let d='';for(let i=0;i<=160;i++){const x=5*i/160,y=mode==='area'?x:x*x,[px,py]=point(x,y);d+=(i?' L':'M')+px.toFixed(1)+' '+py.toFixed(1)}s.append(svg('path',{d,fill:'none',stroke:'#2479ca','stroke-width':3}));
 if(mode!=='area'){const x=params.x,hDelta=params.h,[px,py]=point(x,x*x),[qx,qy]=point(Math.min(5,x+hDelta),Math.pow(Math.min(5,x+hDelta),2));s.append(svg('line',{x1:px,y1:py,x2:qx,y2:qy,stroke:'#e38a38','stroke-width':3}));s.append(svg('circle',{cx:px,cy:py,r:6,fill:'#e38a38'}),svg('circle',{cx:qx,cy:qy,r:6,fill:'#e38a38'}))}
 target.append(s);}
function calcWidget(panel){const isArea=index===2,vars={x:2,h:1,b:4,n:4};const controls=el('div','st216-controls');const graph=el('div','st216-graph');const output=el('div','st216-demo');panel.append(controls,graph,output);
 const xLabel=el('span','st216-value');const hLabel=el('span','st216-value');const bLabel=el('span','st216-value');const nLabel=el('span','st216-value');
 if(!isArea){const x=field(controls,'Position x',range(0,4,.25,vars.x,v=>{vars.x=v;explored();update()}));x.append(xLabel);const h=field(controls,'Window h',range(.05,1,.05,vars.h,v=>{vars.h=v;explored();update()}));h.append(hLabel)}
 else{const b=field(controls,'Upper limit b',range(1,5,.5,vars.b,v=>{vars.b=v;explored();update()}));b.append(bLabel);const n=field(controls,'Number of rectangles',range(2,50,1,vars.n,v=>{vars.n=v;explored();update()}));n.append(nLabel)}
 function update(){if(isArea){bLabel.textContent=nearest(vars.b);nLabel.textContent=String(vars.n);drawGraph(graph,'area',vars);const exact=vars.b*vars.b/2,approx=vars.b*vars.b*(vars.n-1)/(2*vars.n);output.replaceChildren(el('strong','','Total area of y = x from 0 to '+nearest(vars.b)+': '+nearest(exact,2)),el('p','',`Left rectangles estimate ${nearest(approx,2)}. Missing area ≈ ${nearest(exact-approx,2)}. Narrower rectangles reduce the gap.`));}
 else{xLabel.textContent=nearest(vars.x,2);hLabel.textContent=nearest(vars.h,2);drawGraph(graph,'slope',vars);const secant=2*vars.x+vars.h,instant=2*vars.x;output.replaceChildren(el('strong','','Function height: '+nearest(vars.x*vars.x,2)),el('p','',`Average slope over h: ${nearest(secant,2)}. Instantaneous slope at x=${nearest(vars.x,2)}: ${nearest(instant,2)}. As h shrinks, the two slopes approach each other.`));}}
 update();}
function physicsWidget(panel){const configs=[{a:'Distance traveled (m)',b:'Time elapsed (s)',x:20,y:10,minx:5,maxx:100,miny:1,maxy:20},{a:'Net force (newtons)',b:'Mass (kg)',x:10,y:2,minx:0,maxx:50,miny:1,maxy:15},{a:'Drop height (m)',b:'Mass (kg)',x:5,y:2,minx:1,maxx:30,miny:1,maxy:15}],c=configs[index],v={x:c.x,y:c.y};const controls=el('div','st216-controls'),out=el('div','st216-demo');const graph=el('div','st216-physics-graphic');panel.append(controls,graph,out);const xtext=el('span','st216-value'),ytext=el('span','st216-value');field(controls,c.a,range(c.minx,c.maxx,1,v.x,z=>{v.x=z;explored();draw()})).append(xtext);field(controls,c.b,range(c.miny,c.maxy,1,v.y,z=>{v.y=z;explored();draw()})).append(ytext);
 function draw(){xtext.textContent=v.x;ytext.textContent=v.y;graph.replaceChildren();const track=el('div','st216-track');const marker=el('div','st216-object');let val,label,why; if(index===0){val=v.x/v.y;label=nearest(val,2)+' m/s average speed';why=`${v.x} meters ÷ ${v.y} seconds = ${nearest(val,2)} m/s. This does not tell us the acceleration without more information.`;marker.style.left=Math.min(88,8+val*8)+'%'}else if(index===1){val=v.x/v.y;label=nearest(val,2)+' m/s² acceleration';why=`${v.x} N ÷ ${v.y} kg = ${nearest(val,2)} m/s². This assumes the chosen force is the net force.`;marker.style.left=Math.min(88,8+val*8)+'%'}else{val=Math.sqrt(2*9.8*v.x);label=nearest(val,2)+' m/s ideal impact speed';why=`Potential energy: ${nearest(v.y*9.8*v.x,1)} J. Ideal speed: √(2×9.8×${v.x}) = ${nearest(val,2)} m/s. Mass cancels if air resistance is ignored.`;marker.style.left='50%'}marker.textContent=index===2?'↓':'→';track.append(marker);graph.append(track);out.replaceChildren(el('strong','',label),el('p','',why))}draw();}
/* V217: subject-specific learning models; intentionally formative and ungraded. */
