function ensure(){if(dialog)return;dialog=el('dialog','st216-dialog');dialog.id='st216Dialog';dialog.setAttribute('aria-label','Deep teaching workshops');const header=el('header','st216-header');const label=el('div');label.append(el('span','st216-kicker','STUDY TABLE · DEEP TEACHING'),el('h2','','Learn it with me'));header.append(label,btn('Close',close,'st216-close'));const body=el('div','st216-body');body.id='st216Body';dialog.append(header,body);dialog.addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus()});document.body.append(dialog)}
function open(s,i=null){returnFocus=document.activeElement;window.StudyTableTeacher?.close?.();document.getElementById('st213Dialog')?.close();window.StudyTableCalendar?.close?.();ensure();if(SUBJECTS.includes(s)){const start=i===null?TRACKS[s].findIndex((_,k)=>!rec(s,k).done):i;subject=s;index=start>=0?start:0}else{const next=SUBJECTS.find(sub=>TRACKS[sub].some((_,k)=>!rec(sub,k).done));subject=next||'spanish';index=next?TRACKS[next].findIndex((_,k)=>!rec(next,k).done):0}revealModel=false;exploreState={};render();if(!dialog.open)dialog.showModal();$('.st216-close',dialog)?.focus()}
function close(){if(dialog?.open)dialog.close();try{window.speechSynthesis?.cancel?.()}catch{}}
