 const teacher=$('#st214TeacherBody .st214t-tools');if(teacher&&!$('#st216Teacher',teacher)){const b=btn('Go deeper in this subject',()=>{const current=$('#st214TeacherBody .st214t-select')?.value;open(SUBJECTS.includes(current)?current:'spanish')},'st216-teacher-link');b.id='st216Teacher';teacher.append(b)}
