function install(){const obs=new MutationObserver(()=>{if(attach.pending)return;attach.pending=true;queueMicrotask(()=>{attach.pending=false;attach()})});obs.observe(document.body,{childList:true,subtree:true});attach();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else install();
